import{_ as r,o as n,c as o,ao as t}from"./chunks/framework.DlOpO9-F.js";const u=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),i={name:"privacy.md"};function a(s,e,l,d,c,p){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>Effective date: 2026-11-13</p><p>Open Grind Governance, an unregistered project represented by Viktor Shchelochkov, makes the Open Grind app and runs the servers below. Contact: <a href="mailto:admin@opengrind.org" target="_blank" rel="noreferrer">admin@opengrind.org</a></p><h2 id="open-grind-app" tabindex="-1">Open Grind app <a class="header-anchor" href="#open-grind-app" aria-label="Permalink to “Open Grind app”">​</a></h2><p>For the features you use, the app sends data straight to these services over encrypted connections, along with your IP address:</p><p><strong>Required:</strong></p><ul><li><strong>Grindr</strong>: everything you do on Grindr, including sign-in details, profile, photos, messages and location. <a href="https://www.grindr.com/privacy-policy" target="_blank" rel="noreferrer">Policy</a></li><li><strong>OpenStreetMap</strong>: map tiles for the area shown. <a href="https://osmfoundation.org/wiki/Privacy_Policy" target="_blank" rel="noreferrer">Policy</a></li></ul><p><strong>Optional:</strong></p><ul><li>Only when using <strong>Sign in with Google</strong>: <ul><li><strong>Google</strong>: what you enter in Google&#39;s sign-in window. <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Policy</a></li></ul></li><li>Only when using <strong>Sign in with Facebook</strong>: <ul><li><strong>Meta</strong>: what you enter in Facebook&#39;s sign-in window. <a href="https://www.facebook.com/privacy/policy/" target="_blank" rel="noreferrer">Policy</a></li></ul></li><li>Only if you have <strong>enabled GIPHY</strong>: <ul><li><strong>GIPHY</strong>: your GIF searches and language, the GIFs you load, and that you use Grindr. <a href="https://support.giphy.com/hc/en-us/articles/360032872931-GIPHY-Privacy-Policy" target="_blank" rel="noreferrer">Policy</a></li></ul></li><li>Only when using the <strong>reCAPTCHA helper add-on</strong>: <ul><li><strong>Google</strong>: device information, whenever Grindr asks for a captcha. <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Policy</a></li></ul></li><li>Only in <strong>Fast mode</strong> for notifications (the <strong>FCM service add-on</strong>): <ul><li><strong>Google</strong>: this device&#39;s Firebase installation ID and push token, and every notification Grindr sends through Firebase, including sender names and message text. <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Policy</a></li><li><strong>Grindr</strong>: that push token, so it can send your notifications.</li></ul></li></ul><p>To stop sending data, turn the feature off or sign out. To delete data a service holds, ask that service; for Grindr, delete your Grindr account.</p><p>On iOS, a reinstall erases your session, and app data stays out of backups.</p><h2 id="open-grind-servers-and-websites" tabindex="-1">Open Grind servers and websites <a class="header-anchor" href="#open-grind-servers-and-websites" aria-label="Permalink to “Open Grind servers and websites”">​</a></h2><p>Your IP address is only used to answer your requests, and it&#39;s not stored.</p><ul><li><strong>opengrind.org</strong>: this website.</li><li><strong>git.opengrind.org</strong>: the app&#39;s update checks and add-on downloads. <ul><li><em>Only sign-up and sign-in pages</em>: uses <strong>hCaptcha by Intuition Machines (US, certified under the EU-US Data Privacy Framework)</strong>, which gets your IP address and browser data to check that you&#39;re human. <a href="https://www.hcaptcha.com/privacy" target="_blank" rel="noreferrer">Policy</a></li><li><em>Only if you create an account</em>: stores your username, email address and what you post until you delete the account; issues and comments you posted stay under a deleted-user placeholder unless you ask us to remove them.</li></ul></li><li><strong>i18n.opengrind.org</strong>: <ul><li><em>Only if you sign in with your git.opengrind.org account</em>: stores your username and email address until you delete the account, keeps account events for 30 days, and keeps your translations in the project history.</li></ul></li><li><strong>matrix.opengrind.org</strong>: <ul><li><em>Only if you join a Matrix chat room</em>: keeps a copy of the messages and member names of Open Grind&#39;s Matrix rooms for as long as the rooms exist, as every server in a room does.</li></ul></li><li><strong><a href="mailto:admin@opengrind.org" target="_blank" rel="noreferrer">admin@opengrind.org</a></strong>: <ul><li><em>Only if you send an email</em>: keeps your emails until your request is handled.</li></ul></li><li><strong>apns.opengrind.org</strong>: <ul><li><em>Only if you enable notifications on iOS</em>: through your fcm-relay, receives your iPhone&#39;s push token and encrypted notifications, which it can&#39;t read, passes them to <strong>Apple Inc. (US)</strong> with the explicit consent you give when you set it up (GDPR Art. 49(1)(a)), and forgets them within 24 hours. Apple isn&#39;t certified under the EU-US Data Privacy Framework, so EU data protection law may not protect this data in the US. You withdraw this consent by turning notifications off.</li></ul></li></ul><p>Legal basis: our legitimate interest in running these services (GDPR Art. 6(1)(f)).</p><p>You can ask us for access to, correction, deletion or restriction of your data, and complain to a data protection authority.</p><p>You can object to this processing at any time.</p>',17)])])}const h=r(i,[["render",a]]);export{u as __pageData,h as default};
